#include "../include/pbm_lib.h"

#include <stdio.h>


void __print(const pbm_BigInt_ptr big) {
    for (size_t i = 0; i < big->size; ++i) {
        #if ARCH == 32
        printf("chunks[%u] = ", i);
        printf("%u\n", big->chunks[i]);
        #elif ARCH == 64
        printf("chunks[%llu] = ", i);
        printf("%llu\n", big->chunks[i]);
        #endif
    }
}

void __print_pow(const pbm_BigInt_ptr big) {
    for (size_t i = 0; i < big->size; ++i) {
        #if ARCH == 32
        printf("(%u)*((2^%u)^%u)+", big->chunks[i], PBM_digit_bits, i);
        #elif ARCH == 64
        printf("(%llu)*((2^%llu)^%llu)+", big->chunks[i], PBM_digit_bits, i);
        #endif
    }
    printf("0");
}

void test2(void) {
    enum pbm_err e;
    const char* t[] = {"01010101", "101", "00000", "AEEEEEEEE", "012341234",
    "010101011010100101010110101010010010010101010101011010101010101101010101011111111100101011010101010"};
    struct pbm_BigInt* h = pbm_BigInt_create_s(t[5], bin, 0, &e);

    __print(h);
    __print_pow(h);
}




void test(void) {
    printf("Architecture is %d %d\n", sizeof(void*), PBM_digit_bits);

    enum pbm_err e;
    const char* strs[] = {
    "1234567890700001234567",
    "4294967297",
    "12345678900",
    "13333744860005217",
    "18446744073709551616",
    "1",
    "1223666790471429673200215411579542",
    "29469611466878894144725566641577883900641390559558271790792717420960039123711471008640298676332121543228653836270563658439343545591490408347353197391442346432374720917764845725447313263871608490058977344434378833976291501949964310603274734",
    ""
};
    FILE* f = fopen("./test.txt", "w");
    struct pbm_BigInt* Big = pbm_BigInt_create_s(strs[8], dec, 0, &e); 
    printf("size = %d\n\n", Big->size);
    for (size_t i = 0; i < Big->size; ++i) {
        pbm_digit_t view = Big->chunks[i];
        fprintf(f, "(%u*((2**(32))**", view);
        fprintf(f, "(%u)))+", i);
    }
    fprintf(f, "0");
    printf("\n\n");

    fclose(f);
    #if 0
    char* str = pbm_BigInt_str(Big);
    printf("Digit: %s", str);
    #endif
}

